            PNCCapabilities.getAirHandler(pStack).ifPresent(srcHandler -> {
                for (ItemStack stack : mode.getStacksToCharge(player)) {
                    if (srcHandler.getPressure() < 0.1F) return;
                    if (stack.getCount() == 1 && stack != pStack && !isChargingAirCanister(stack)) {
                        tryChargeItem(srcHandler, stack, type.maxTransfer);
                    }
                }
            });
        }
    }

@Override
    public InteractionResultHolder<ItemStack> use(Level pLevel, Player pPlayer, InteractionHand pUsedHand) {
        ItemStack stack = pPlayer.getItemInHand(pUsedHand);
        if (!pLevel.isClientSide) {
            ChargeMode mode = getChargeMode(stack).nextMode();
            pPlayer.getItemInHand(pUsedHand).set(ModDataComponents.CHARGING_MODE, mode);
            pPlayer.displayClientMessage(xlate(mode.getTranslationKey()).withStyle(ChatFormatting.AQUA), true);
        }
        return InteractionResultHolder.sidedSuccess(stack, pLevel.isClientSide);
    }

public static ChargeMode getChargeMode(ItemStack stack) {
        return stack.getOrDefault(ModDataComponents.CHARGING_MODE, ChargeMode.NONE);
    }

private static boolean isChargingAirCanister(ItemStack stack) {
        return stack.getItem() instanceof AirCanisterItem && getChargeMode(stack) != ChargeMode.NONE;
    }

private void tryChargeItem(IAirHandler srcHandler, ItemStack dstStack, int maxAir) {
        PNCCapabilities.getAirHandler(dstStack).ifPresent(destHandler -> {
            float destPressure = destHandler.getPressure();
            if (destPressure < destHandler.maxPressure() && (destPressure - srcHandler.getPressure()) < -0.01f) {
                float targetPressure = Math.min((srcHandler.getPressure() + destHandler.getPressure()) / 2f, destHandler.maxPressure());
                int currentAir = destHandler.getAir();
                int targetAir = (int) (targetPressure * destHandler.getVolume());
                int airToMove = Mth.clamp(targetAir - currentAir, 0, maxAir);
                destHandler.addAir(airToMove);
                srcHandler.addAir(-airToMove);
            }
        });
    }

public List<ItemStack> getStacksToCharge(Player player) {
        List<ItemStack> toCharge = new ArrayList<>();
        if (shouldChargeArmor()) {
            toCharge.add(player.getItemBySlot(EquipmentSlot.HEAD));
            toCharge.add(player.getItemBySlot(EquipmentSlot.LEGS));
            toCharge.add(player.getItemBySlot(EquipmentSlot.FEET));
        }
        if (shouldChargeHeldItem()) {
            toCharge.add(player.getItemBySlot(EquipmentSlot.MAINHAND));
            toCharge.add(player.getItemBySlot(EquipmentSlot.OFFHAND));
        }
        if (this == ChargeMode.ALL) {
            toCharge.addAll(player.getInventory().items);
        }
        return toCharge;
    }

@SubscribeEvent
	public void onLivingDeath(LivingDeathEvent event) {
		if (event.getEntity() instanceof Player && !event.getEntity().level().isClientSide) {
			Player player = (Player) event.getEntity();

			if (SuperpositionHandler.isTheBlessedOne(player)) {
				ItemStack scroll = SuperpositionHandler.getCurioStack(player, this);

				if (scroll != null && !this.hasCooldown(scroll)) {
					event.setCanceled(true);
					player.setHealth(player.getMaxHealth() / 2);

					player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 1200, 2));
					player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 1200, 1));
					player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 1200, 0));
					player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 1200, 1));

					this.setCooldown(scroll, deathProtectionCooldown.getValue() * 20);

					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() ->
					new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128,
							player.level().dimension())), new PacketCosmicRevive(player.getId(), 0));
				}
			}
		}
	}

public boolean hasCooldown(ItemStack scroll) {
		return this.getCooldown(scroll) > 0;
	}

public int getCooldown(ItemStack scroll) {
		if (scroll.is(this))
			return ItemNBTHelper.getInt(scroll, "ReviveCooldown", 0);
		else
			return 0;
	}

public void setCooldown(ItemStack scroll, int cooldown) {
		if (scroll.is(this)) {
			ItemNBTHelper.setInt(scroll, "ReviveCooldown", cooldown);
		}
	}

