public static ItemStack consumeItemStack(Predicate<ItemStack> itemMatches, Player player, int count) {
		return extractFromInventory(itemMatches, count, getMainInventoryItemHandlerFrom(player), false);
	}

public static ItemStack extractFromInventory(Predicate<ItemStack> itemMatches, int count, IItemHandler inventory, boolean simulate) {
		ItemStack ret = ItemStack.EMPTY;
		int slots = inventory.getSlots();
		for (int slot = 0; slot < slots && ret.getCount() < count; slot++) {
			ItemStack slotStack = inventory.getStackInSlot(slot);
			if (itemMatches.test(slotStack) && (ret.isEmpty() || ItemStack.isSameItemSameComponents(ret, slotStack))) {
				int toExtract = Math.min(slotStack.getCount(), count - ret.getCount());
				ItemStack extractedStack = inventory.extractItem(slot, toExtract, simulate);
				if (ret.isEmpty()) {
					ret = extractedStack;
				} else {
					ret.setCount(ret.getCount() + extractedStack.getCount());
				}
			}
		}
		return ret;
	}

public static float getDamageAbsorbed(LivingEntity entity, DamageSource source, float amount) {
        if (amount <= 0) {
            return 0;
        }
        float ratioAbsorbed = 0;
        List<FoundArmorDetails> armorDetails = new ArrayList<>();
        //Protect against any mods that might be doing transactional logic, such as if an auto clicker validates it has enough energy before calling this method
        try (Transaction transaction = TransactionHelper.openTransactionSafe()) {
            //Start by looping the armor, allowing modules to absorb damage if they can
            for (EquipmentSlot armorType : EquipmentSlotGroup.ARMOR) {
                //Player's don't have non-humanoid armor and the wrapper will throw for them, so skip them
                if (!(entity instanceof Player) || armorType.getType() == Type.HUMANOID_ARMOR) {
                    ResourceHandler<ItemResource> armorSlot = LivingEntityEquipmentWrapper.of(entity, armorType);
                    ItemResource itemType = armorSlot.getResource(0);
                    if (!itemType.isEmpty() && itemType.is(MekanismAPITags.Items.MODULE_CONTAINERS_ARMOR)) {
                        ItemAccess itemAccess = ItemAccess.forHandlerIndexStrict(armorSlot, 0);
                        EnergyHandler energyHandler = AutomatedEnergyHandler.manual(Capabilities.ENERGY.getCapability(itemAccess));
                        if (energyHandler != null) {
                            FoundArmorDetails details = new FoundArmorDetails(energyHandler, getAbsorption(armorType));
                            armorDetails.add(details);
                            for (IModule<?> module : IModuleHelper.INSTANCE.getAllModules(itemType)) {
                                if (module.isEnabled()) {
                                    ModuleDamageAbsorbInfo damageAbsorbInfo = getModuleDamageAbsorbInfo(module, source);
                                    if (damageAbsorbInfo != null) {
                                        float absorption = damageAbsorbInfo.absorptionRatio().getAsFloat();
                                        ratioAbsorbed += absorbDamage(details.energyHandler, amount, absorption, ratioAbsorbed, damageAbsorbInfo.energyCost(), transaction);
                                        if (ratioAbsorbed >= 1) {
                                            //If we have fully absorbed the damage, stop checking/trying to absorb more
                                            break;
                                        }
                                    }
                                }
                            }
                            if (ratioAbsorbed >= 1) {
                                //If we have fully absorbed the damage, stop checking/trying to absorb more
                                break;
                            }
                        }
                    }
                }
            }
            if (ratioAbsorbed < 1) {
                //If we haven't fully absorbed it check the individual pieces of armor for if they can absorb any
                Float absorbRatio = null;
                for (FoundArmorDetails details : armorDetails) {
                    if (absorbRatio == null) {
                        //If we haven't looked up yet if we can absorb the damage type and if we can't
                        // stop checking if the armor is able to
                        if (source.is(Tags.DamageTypes.IS_TECHNICAL) || !source.is(MekanismAPITags.DamageTypes.MEKASUIT_ALWAYS_SUPPORTED) && source.is(DamageTypeTags.BYPASSES_ARMOR)) {
                            break;
                        }
                        // Next lookup the ratio at which we can absorb the given damage type from the data map
                        MekaSuitAbsorption absorptionData = IMekanismDataMapTypes.INSTANCE.getMekaSuitAbsorption(entity.registryAccess(), source.typeHolder());
                        if (absorptionData == null) {
                            absorbRatio = MekanismConfig.gear.mekaSuitUnspecifiedDamageRatio.get();
                        } else {
                            absorbRatio = absorptionData.absorption();
                        }
                        if (absorbRatio == 0) {
                            //If the config or the data map specifies that the damage type shouldn't be blocked at all
                            // stop checking if the armor is able to
                            break;
                        }
                    }
                    float absorption = details.armorAbsorption * absorbRatio;
                    ratioAbsorbed += absorbDamage(details.energyHandler, amount, absorption, ratioAbsorbed, MekanismConfig.gear.mekaSuitEnergyUsageDamage, transaction);
                    if (ratioAbsorbed >= 1) {
                        //If we have fully absorbed the damage, stop checking/trying to absorb more
                        break;
                    }
                }
            }
            //Use energy/or enqueue usage for each piece as needed
            transaction.commit();
        }
        return Math.min(ratioAbsorbed, 1);
    }

@SubscribeEvent
    public void onEntityAttacked(LivingIncomingDamageEvent event) {
        LivingEntity entity = event.getEntity();
        DamageContainer damageContainer = event.getContainer();
        float damage = damageContainer.getNewDamage();
        if (damage <= 0 || !entity.isAlive()) {
            //If some mod does weird things and causes the damage value to be negative or zero then exit
            // as our logic assumes there is actually damage happening and can crash if someone tries to
            // use a negative number as the damage value. We also check to make sure that we don't do
            // anything if the entity is dead as living attack is still fired when the entity is dead
            // for things like fall damage if the entity dies before hitting the ground, and then energy
            // would be depleted regardless if keep inventory is on even if no damage was stopped as the
            // entity can't take damage while dead
            return;
        }
        DamageSource source = damageContainer.getSource();
        //Gas Mask checks
        if (source.is(MekanismAPITags.DamageTypes.IS_PREVENTABLE_MAGIC)) {
            ItemStack headStack = entity.getItemBySlot(EquipmentSlot.HEAD);
            if (!headStack.isEmpty() && headStack.getItem() instanceof ItemScubaMask) {
                ItemAccess chestAccess = ItemAccessUtils.forEntitySlot(entity, EquipmentSlot.CHEST);
                if (chestAccess.getResource().getItem() instanceof ItemScubaTank tank && tank.getMode(chestAccess) && tank.hasChemical(chestAccess)) {
                    event.setCanceled(true);
                    return;
                }
            }
        }
        for (EquipmentSlot slot : EquipmentSlotGroup.ARMOR) {
            if (entity.getItemBySlot(slot).is(MekanismAPITags.Items.MODULE_CONTAINERS_ARMOR)) {
                //Only add the reduction modifier if at least one module container armor is being worn
                event.addReductionModifier(Reduction.ARMOR, (container, reduction) -> {
                    float newDamage = container.getNewDamage();
                    if (newDamage > reduction) {
                        //Note: This acts on the damage after the reduction from armor has been performed
                        float toReduce = newDamage - reduction;
                        float ratioAbsorbed = Math.max(0, ItemMekaSuitArmor.getDamageAbsorbed(entity, container.getSource(), toReduce));
                        if (ratioAbsorbed > 0) {
                            if (ratioAbsorbed >= 1) {
                                //If we fully absorbed the damage, mark that we don't want side effects to be performed
                                container.setShouldCauseSideEffects(false);
                                //And just return that we reduced all the damage so that we don't have to worry about floating point nonsense
                                return newDamage;
                            }
                            return reduction + toReduce * ratioAbsorbed;
                        }
                    }
                    return reduction;
                });
                break;
            }
        }
    }

@Nullable
    private static <MODULE extends ICustomModule<MODULE>> ModuleDamageAbsorbInfo getModuleDamageAbsorbInfo(IModule<MODULE> module, DamageSource damageSource) {
        return module.getCustomInstance().getDamageAbsorbInfo(module, damageSource);
    }

private static float absorbDamage(EnergyHandler energyHandler, float amount, float absorption, float currentAbsorbed, IntSupplier energyCost, TransactionContext transaction) {
        //Cap the amount that we can absorb to how much we have left to absorb
        absorption = Math.min(1 - currentAbsorbed, absorption);
        float toAbsorb = amount * absorption;
        if (toAbsorb > 0) {
            int usage = Mth.ceil(energyCost.getAsInt() * toAbsorb);
            if (usage == 0) {
                //No energy is actually needed to absorb the damage, either because of the config
                // or how small the amount to absorb is
                return absorption;
            }
            int energyUsed = energyHandler.extract(usage, transaction);
            if (energyUsed == usage) {
                //If we have more energy available than we need, return that we can absorb it all
                return absorption;
            } else if (energyUsed > 0) {
                //Otherwise, if we have energy available but not as much as needed to fully absorb it
                // then we calculate what ratio we are able to block
                float absorbedPercent = energyUsed / (float) usage;
                return absorption * absorbedPercent;
            }
        }
        return 0;
    }

public void applyEffectTick(LivingEntity LivingEntityIn, int amplifier) {
        boolean flag =   LivingEntityIn.hurt(LivingEntityIn.damageSources().source(CMDamageTypes.ABYSSAL_BURN), 1.0F);
        if(flag && LivingEntityIn.getRandom().nextFloat() < (0.75f - LivingEntityIn.getHealth() / LivingEntityIn.getMaxHealth())) {
            if (!LivingEntityIn.level().isClientSide) {
                double d0 = LivingEntityIn.getX();
                double d1 = LivingEntityIn.getY();
                double d2 = LivingEntityIn.getZ();

                for (int i = 0; i < 8; ++i) {
                    double d3 = LivingEntityIn.getX() + (LivingEntityIn.getRandom().nextDouble() - 0.5D) * 8.0D;
                    double d4 = Mth.clamp(LivingEntityIn.getY() + (double) (LivingEntityIn.getRandom().nextInt(8) - 4), (double) LivingEntityIn.level().getMinBuildHeight(), (double) (LivingEntityIn.level().getMinBuildHeight() + ((ServerLevel) LivingEntityIn.level()).getLogicalHeight() - 1));
                    double d5 = LivingEntityIn.getZ() + (LivingEntityIn.getRandom().nextDouble() - 0.5D) * 8.0D;
                    if (LivingEntityIn.isPassenger()) {
                        LivingEntityIn.stopRiding();
                    }
                    Vec3 vec3 = LivingEntityIn.position();
                    LivingEntityIn.level().gameEvent(GameEvent.TELEPORT, vec3, GameEvent.Context.of(LivingEntityIn));
                    net.minecraftforge.event.entity.EntityTeleportEvent.ChorusFruit event = net.minecraftforge.event.ForgeEventFactory.onChorusFruitTeleport(LivingEntityIn, d3, d4, d5);
                    if (randomTeleportInwater(LivingEntityIn,event.getTargetX(), event.getTargetY(), event.getTargetZ(), true)) {
                        SoundEvent soundevent = LivingEntityIn instanceof Fox ? SoundEvents.FOX_TELEPORT : SoundEvents.CHORUS_FRUIT_TELEPORT;
                        LivingEntityIn.level().playSound((Player) null, d0, d1, d2, soundevent, SoundSource.PLAYERS, 1.0F, 1.0F);
                        LivingEntityIn.playSound(soundevent, 1.0F, 1.0F);
                        break;
                    }
                }

            }
        }
    }

private boolean randomTeleportInwater(LivingEntity LivingEntityIn,double p_20985_, double p_20986_, double p_20987_, boolean p_20988_) {
        double d0 = LivingEntityIn.getX();
        double d1 = LivingEntityIn.getY();
        double d2 = LivingEntityIn.getZ();
        double d3 = p_20986_;
        boolean flag = false;
        BlockPos blockpos = BlockPos.containing(p_20985_, p_20986_, p_20987_);
        Level level = LivingEntityIn.level();
        if (level.hasChunkAt(blockpos)) {
            boolean flag1 = false;

            while(!flag1 && blockpos.getY() > level.getMinBuildHeight()) {
                BlockPos blockpos1 = blockpos.below();
                BlockState blockstate = level.getBlockState(blockpos1);
                if (blockstate.blocksMotion()) {
                    flag1 = true;
                } else {
                    --d3;
                    blockpos = blockpos1;
                }
            }

            if (flag1) {
                LivingEntityIn.teleportTo(p_20985_, d3, p_20987_);
                if (level.noCollision(LivingEntityIn)) {
                    flag = true;
                }
            }
        }

        if (!flag) {
            LivingEntityIn.teleportTo(d0, d1, d2);
            return false;
        } else {
            if (p_20988_) {
                level.broadcastEntityEvent(LivingEntityIn, (byte)46);
            }

            if (LivingEntityIn instanceof PathfinderMob) {
                ((PathfinderMob)LivingEntityIn).getNavigation().stop();
            }

            return true;
        }
    }

public boolean isDurationEffectTick(int duration, int amplifier) {
        int k = 50 >> amplifier;
        if (k > 0) {
            return duration % k == 0;
        } else {
            return true;
        }
    }
